_GRADE_WINDOWS_SCHEMA = "climate-grid/rw"
_GRADE_WINDOWS_ITEM_KEYS = ("name", "start", "end")
_GRADE_WINDOWS_OUTPUT_KEYS = ("schema", "windows", "scenarios", "data")
_GRADE_WINDOWS_ROW_KEYS = (
    "window",
    "scenario",
    "valid",
    "count",
    "transitions",
    "stability",
    "trend",
)
_GRADE_WINDOWS_LEVEL_SCORES = {"strong": 0, "moderate": 1, "conflict": 2}
_GRADE_WINDOWS_ALL_LEVELS = ("missing",) + _GRADE_HISTORY_LEVELS


def _validate_grade_history(
    history: Any,
) -> tuple[list[str], list[str], list[list[str]]]:
    """Validate a complete :func:`grade_history` result.

    Returns the ``periods`` axis, the ``scenarios`` axis and the
    per-scenario per-period levels, checking the
    ``climate-grid/rgh-v1`` contract: key order, the echoed axes and
    the recomputed ``valid``/``count``/``transitions``/``changes``
    values of every row.  A ``rate`` of ``None`` is accepted for any
    ``count`` below the (unreported) generation ``minimum``; any
    present ``rate`` must equal the rounded ``changes / count``.
    """
    if not isinstance(history, dict):
        raise TypeError("history must be a dict")
    if tuple(history.keys()) != _GRADE_HISTORY_OUTPUT_KEYS:
        raise ValueError(
            "history must have exactly the keys schema, periods, "
            "scenarios, data in order"
        )

    schema = history["schema"]
    if not isinstance(schema, str):
        raise TypeError("history.schema must be a str")
    if schema != _GRADE_HISTORY_SCHEMA:
        raise ValueError(
            f"history.schema must be {_GRADE_HISTORY_SCHEMA!r}"
        )

    periods = history["periods"]
    if not isinstance(periods, list):
        raise TypeError("history.periods must be a list")
    if len(periods) < 2:
        raise ValueError("history.periods must contain at least 2 periods")
    seen_periods: set[str] = set()
    for index, period in enumerate(periods):
        where = f"history.periods[{index}]"
        if not isinstance(period, str):
            raise TypeError(f"{where} must be a str")
        if period == "":
            raise ValueError(f"{where} must be non-empty")
        if period in seen_periods:
            raise ValueError(f"duplicate history period: {period!r}")
        seen_periods.add(period)

    scenarios = history["scenarios"]
    if not isinstance(scenarios, list):
        raise TypeError("history.scenarios must be a list")
    if not scenarios:
        raise ValueError("history.scenarios must be non-empty")
    seen_scenarios: set[str] = set()
    for index, scenario in enumerate(scenarios):
        where = f"history.scenarios[{index}]"
        if not isinstance(scenario, str):
            raise TypeError(f"{where} must be a str")
        if scenario == "":
            raise ValueError(f"{where} must be non-empty")
        if scenario in seen_scenarios:
            raise ValueError(f"duplicate history scenario: {scenario!r}")
        seen_scenarios.add(scenario)

    data = history["data"]
    if not isinstance(data, list):
        raise TypeError("history.data must be a list")
    if len(data) != len(scenarios):
        raise ValueError(
            "history.data must contain exactly one row per scenario"
        )

    n_periods = len(periods)
    level_index = {
        level: i for i, level in enumerate(_GRADE_HISTORY_LEVELS)
    }
    levels_by_scenario: list[list[str]] = []
    for row_index, row in enumerate(data):
        where = f"history.data[{row_index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(row.keys()) != _GRADE_HISTORY_ROW_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys scenario, total, "
                "valid, levels, count, transitions, changes, rate in "
                "order"
            )

        scenario = row["scenario"]
        if not isinstance(scenario, str):
            raise TypeError(f"{where}.scenario must be a str")
        if scenario != scenarios[row_index]:
            raise ValueError(
                f"{where}.scenario {scenario!r} must equal "
                f"history.scenarios[{row_index}] "
                f"({scenarios[row_index]!r})"
            )

        total = row["total"]
        if not isinstance(total, int) or isinstance(total, bool):
            raise TypeError(f"{where}.total must be a non-bool int")
        if total != n_periods:
            raise ValueError(
                f"{where}.total must equal the number of periods"
            )

        levels = row["levels"]
        if not isinstance(levels, list):
            raise TypeError(f"{where}.levels must be a list")
        if len(levels) != total:
            raise ValueError(
                f"{where}.levels must contain one level per period"
            )
        for level_index_pos, level in enumerate(levels):
            level_where = f"{where}.levels[{level_index_pos}]"
            if not isinstance(level, str):
                raise TypeError(f"{level_where} must be a str")
            if level not in _GRADE_WINDOWS_ALL_LEVELS:
                raise ValueError(
                    f"{level_where} must be one of missing, strong, "
                    "moderate, conflict"
                )

        expected_valid = sum(level != "missing" for level in levels)
        valid = row["valid"]
        if not isinstance(valid, int) or isinstance(valid, bool):
            raise TypeError(f"{where}.valid must be a non-bool int")
        if valid != expected_valid:
            raise ValueError(
                f"{where}.valid must equal the number of non-missing "
                "levels"
            )

        expected_transitions = [0 for _ in range(9)]
        expected_count = 0
        expected_changes = 0
        for earlier, later in zip(levels, levels[1:]):
            if earlier == "missing" or later == "missing":
                continue
            expected_count += 1
            expected_transitions[
                level_index[earlier] * 3 + level_index[later]
            ] += 1
            if earlier != later:
                expected_changes += 1

        count = row["count"]
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError(f"{where}.count must be a non-bool int")
        if count != expected_count:
            raise ValueError(
                f"{where}.count must equal the number of adjacent "
                "non-missing level pairs"
            )

        transitions = row["transitions"]
        if not isinstance(transitions, list):
            raise TypeError(f"{where}.transitions must be a list")
        if len(transitions) != 9:
            raise ValueError(
                f"{where}.transitions must contain exactly 9 items"
            )
        for transition_index, transition in enumerate(transitions):
            transition_where = f"{where}.transitions[{transition_index}]"
            if not isinstance(transition, int) or isinstance(
                transition, bool
            ):
                raise TypeError(f"{transition_where} must be a non-bool int")
            if transition < 0:
                raise ValueError(f"{transition_where} must be non-negative")
        if transitions != expected_transitions:
            raise ValueError(
                f"{where}.transitions must count the adjacent "
                "non-missing level pairs"
            )

        changes = row["changes"]
        if not isinstance(changes, int) or isinstance(changes, bool):
            raise TypeError(f"{where}.changes must be a non-bool int")

def _validate_window_rank(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], list]:
    """Validate a complete :func:`window_rank` result.

    Returns the window names (in data order), the shared scenario order
    and, per window, the scenario means (floats or ``None``).
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _REGION_WINDOW_RANK_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _REGION_WINDOW_RANK_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_REGION_WINDOW_RANK_SCHEMA!r}"
        )

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) == 0:
        raise ValueError(f"{where}.data must be non-empty")

    for index, row in enumerate(data):
        row_where = f"{where}.data[{index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _REGION_WINDOW_RANK_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys window, scenario, "
                "total, valid, missing_rate, mean, best, worst, stddev "
                "in order"
            )

        window = row["window"]
        if not isinstance(window, str):
            raise TypeError(f"{row_where}.window must be a str")
        if window == "":
            raise ValueError(f"{row_where}.window must be non-empty")
        scenario = row["scenario"]
        if not isinstance(scenario, str):
            raise TypeError(f"{row_where}.scenario must be a str")
        if scenario == "":
            raise ValueError(f"{row_where}.scenario must be non-empty")

        total = row["total"]
        if not isinstance(total, int) or isinstance(total, bool):
            raise TypeError(f"{row_where}.total must be a non-bool int")
        if total < 1:
            raise ValueError(f"{row_where}.total must be positive")
        valid = row["valid"]
        if not isinstance(valid, int) or isinstance(valid, bool):
            raise TypeError(f"{row_where}.valid must be a non-bool int")
        if valid < 0:
            raise ValueError(f"{row_where}.valid must be non-negative")
        if valid > total:
            raise ValueError(
                f"{row_where}.valid must not exceed {row_where}.total"
            )

        _validate_number(
            row["missing_rate"], f"{row_where}.missing_rate", nullable=False
        )
        if row["missing_rate"] != _round_output((total - valid) / total):
            raise ValueError(
                f"{row_where}.missing_rate must equal "
                "(total - valid) / total"
            )

        stat_fields = ("mean", "best", "worst", "stddev")
        _validate_number(row["mean"], f"{row_where}.mean", nullable=True)
        _validate_number(row["stddev"], f"{row_where}.stddev", nullable=True)
        for name in ("best", "worst"):
            value = row[name]
            if value is None:
                continue
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(f"{row_where}.{name} must be a non-bool int")
            if value < 1:
                raise ValueError(f"{row_where}.{name} must be positive")

        none_flags = [row[name] is None for name in stat_fields]
        if any(none_flags) and not all(none_flags):
            raise ValueError(
                f"{row_where}: mean, best, worst and stddev must be all "
                "None or all present"
            )
        if valid == 0 and not all(none_flags):
            raise ValueError(
                f"{row_where}: mean, best, worst and stddev must be None "
                "when valid is zero"
            )
        if not any(none_flags):
            if row["best"] > row["worst"]:
                raise ValueError(
                    f"{row_where}.best must not exceed {row_where}.worst"
                )
            if not (row["best"] <= row["mean"] <= row["worst"]):
                raise ValueError(
                    f"{row_where}.mean must lie between best and worst"
                )
            if row["stddev"] < 0:
                raise ValueError(f"{row_where}.stddev must be non-negative")

    windows: list[str] = []
    scenario_order: list[str] | None = None
    means: list[list] = []
    seen_windows: set[str] = set()
    index = 0
    n_rows = len(data)
    while index < n_rows:
        window = data[index]["window"]
        if window in seen_windows:
            raise ValueError(
                f"{where}.data rows for window {window!r} must form a "
                "single contiguous block"
            )
        seen_windows.add(window)
        block_scenarios = []
        block_means = []
        while index < n_rows and data[index]["window"] == window:
            block_scenarios.append(data[index]["scenario"])
            block_means.append(data[index]["mean"])
            index += 1
        if len(set(block_scenarios)) != len(block_scenarios):
            raise ValueError(
                f"{where}.data window {window!r} lists a scenario more "
                "than once"
            )
        if scenario_order is None:
            scenario_order = block_scenarios
        elif block_scenarios != scenario_order:
            raise ValueError(
                f"{where}.data window {window!r} must list the same "
                "scenarios in the same order as the first window"
            )
        windows.append(window)
        means.append(block_means)

    return windows, scenario_order, means


