def mkrow(w, sc, valid, count, trans, st, tr):
    return {"window": w, "scenario": sc, "valid": valid, "count": count,
            "transitions": trans, "stability": st, "trend": tr}
wins=[{"name":"w1","start":"p1","end":"p2"},{"name":"w2","start":"p3","end":"p4"},{"name":"w3","start":"p5","end":"p6"}]
scs=["a","b"]
data=[mkrow("w1","a",2,1,t,1.0,0.5),mkrow("w1","b",2,1,t,0.0,None),
      mkrow("w2","a",2,1,t,0.0,1.5),mkrow("w2","b",2,1,t,None,None),
      mkrow("w3","a",2,1,t,1.0,-0.0),mkrow("w3","b",2,1,t,1.0,2.0)]
r={"schema":"climate-grid/rw","windows":wins,"scenarios":scs,"data":data}

# the checks in original order after the arithmetic block
out2 = s.grade_window_changes(r, minimum=3)
assert out2["data"][0]["mean"] is None and out2["data"][0]["peak"] is None
assert out2["data"][0]["count"] == 2

r1 = {"schema":"climate-grid/rw","windows":wins[:1],"scenarios":scs,"data":data[:2]}
try:
    s.grade_window_changes(r1); print("FAIL one-window")
except ValueError: print("ok one-window")

# wrong key order
try:
    s.grade_window_changes({"windows":wins,"scenarios":scs,"data":data,"schema":"climate-grid/rw"}); print("FAIL order")
except ValueError: print("ok order")

# wrong schema
try:
    s.grade_window_changes({**r,"schema":"x"}); print("FAIL schema")
except ValueError: print("ok schema")

# non-dict
try: s.grade_window_changes(42); print("FAIL nondict")
except TypeError: print("ok nondict")

# stability str
rbad=copy.deepcopy(r); rbad["data"][0]["stability"]="x"
try: s.grade_window_changes(rbad); print("FAIL stab str")
except TypeError: print("ok stab str")

# valid bool
rbad=copy.deepcopy(r); rbad["data"][0]["valid"]=True
try: s.grade_window_changes(rbad); print("FAIL valid bool")
except TypeError: print("ok valid bool")

# count=5 vs valid=2 -> count > valid-1
rbad=copy.deepcopy(r); rbad["data"][0]["count"]=5
try: s.grade_window_changes(rbad); print("FAIL count5")
except ValueError: print("ok count5")

# transitions len 8
rbad=copy.deepcopy(r); rbad["data"][0]["transitions"]=[0]*8
try: s.grade_window_changes(rbad); print("FAIL t8")
except ValueError: print("ok t8")

# window item tuple
rbad=copy.deepcopy(r); rbad["windows"][0]=("w1","p1","p2")
try: s.grade_window_changes(rbad); print("FAIL wtuple")
except TypeError: print("ok wtuple")

# dup name w2  (renames w1->w2, so dup w2; but data rows window still w1! -> row window mismatch ValueError earlier)
rbad=copy.deepcopy(r); rbad["windows"][0]["name"]="w2"
try: s.grade_window_changes(rbad); print("FAIL dupname")
except ValueError: print("ok dupname")

# scenario mismatch
rbad=copy.deepcopy(r); rbad["data"][0]["scenario"]="b"
try: s.grade_window_changes(rbad); print("FAIL scmismatch")
except ValueError: print("ok scmismatch")

for m,exc in [(True,TypeError),(0,ValueError),(-1,ValueError),(1.0,TypeError),("1",TypeError)]:
    try: s.grade_window_changes(r,minimum=m); print(f"FAIL min {m}")
    except exc: print(f"ok min {m}")
